from itertools import product

def check_p(p, max_k=6):
    # We are looking for a sequence a_i in {-2, -1, 0, 1, 2}
    # such that sum_{i=1}^k a_i * p^i = 0 and not all a_i are 0.
    for k in range(1, max_k + 1):
        for coeffs in product([-2, -1, 0, 1, 2], repeat=k):
            if all(c == 0 for c in coeffs):
                continue
            s = sum(c * (p**i) for i, c in enumerate(coeffs, 1))
            if abs(s) < 1e-9:
                return True
    return False

test_ps = [1, 0.5, 2, 3, 1/3, 1.5, 2/3, 2.5, 0.4, 0.6, 0.8]
results = {p: check_p(p) for p in test_ps}
print(results)
